import { createToaster } from "@chakra-ui/react";
import type { ShowToastFn, UpdateToastFn, DismissToastFn, IsToastVisibleFn } from "../types/toast";

export const toaster = createToaster({
  placement: "bottom-end",
  pauseOnPageIdle: true,
});

export const defaultShowToast: ShowToastFn = (options) => {
  if (!options.title && !options.description) {
    return;
  }
  toaster.create(options);
};

export const defaultUpdateToast: UpdateToastFn = (id, options) => {
  toaster.update(id, options);
};

export const defaultDismissToast: DismissToastFn = (id) => {
  toaster.dismiss(id);
};

export const defaultIsToastVisible: IsToastVisibleFn = (id) => {
  return toaster.isVisible(id);
};
